mapper.update:
UPDATE sub_goal
SET learned_hours = GREATEST(0, COALESCE(learned_hours, 0) + #{hoursDelta}),
    update_time = NOW()
WHERE id = #{subGoalId}
  AND stage_id = #{stageGoalId}
  AND user_id = #{userId}

UPDATE sub_goal
SET status = #{status},
    completed_time = #{completedTime},
    update_time = NOW()
WHERE id = #{subGoalId}
  AND stage_id = #{stageGoalId}
  AND user_id = #{userId}

UPDATE stage_goal
SET status = #{status},
    completed_time = #{completedTime},
    update_time = NOW()
WHERE id = #{stageGoalId}
  AND user_id = #{userId}

