SELECT checkin_type
FROM goal_checkin
WHERE sub_goal_id = #{subGoalId}
  AND stage_goal_id = #{stageGoalId}
  AND user_id = #{userId}
  AND is_deleted = 0
  AND checkin_type IN (2, 3)
ORDER BY checkin_date DESC, create_time DESC, id DESC
LIMIT 1

